import { pgEnum, timestamp, uuid } from "drizzle-orm/pg-core";

// Relative import on purpose: drizzle-kit loads this folder without the `@/` alias.
import { locales } from "../../config/enums";

export const localeEnum = pgEnum("locale", locales);

/**
 * UUID primary key generated by Postgres. `gen_random_uuid()` is v4; PostgreSQL 17 has no
 * `uuidv7()` yet, so the column switches to it when the server is upgraded (ADR-023).
 */
export const id = () => uuid().primaryKey().defaultRandom();

/** `created_at` / `updated_at` for every content table (AGENTS.md § 4). */
export const timestamps = {
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/** Soft delete: rows with `deleted_at` set are hidden everywhere but kept for audit. */
export const softDelete = {
  deletedAt: timestamp({ withTimezone: true }),
};
